-- Secure DataSub transaction PIN authorization
create table if not exists public.datasub_transaction_pins(user_id uuid primary key references public.profiles(id) on delete cascade,pin_hash text not null,failed_attempts integer not null default 0,locked_until timestamptz,updated_at timestamptz not null default now());
alter table public.datasub_transaction_pins enable row level security; revoke all on public.datasub_transaction_pins from anon,authenticated; grant all on public.datasub_transaction_pins to service_role;
create or replace function public.datasub_has_transaction_pin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.datasub_transaction_pins where user_id=auth.uid())$$;
revoke all on function public.datasub_has_transaction_pin() from public,anon; grant execute on function public.datasub_has_transaction_pin() to authenticated,service_role;
create or replace function public.set_datasub_transaction_pin(p_pin text,p_current_pin text default null) returns void language plpgsql security definer set search_path='' as $$declare uid uuid:=auth.uid(); old public.datasub_transaction_pins; begin if uid is null then raise exception 'Authentication required'; end if; if p_pin !~ '^[0-9]{4}$' then raise exception 'PIN must be exactly 4 digits'; end if; select * into old from public.datasub_transaction_pins where user_id=uid for update; if old.user_id is not null and (p_current_pin is null or extensions.crypt(p_current_pin,old.pin_hash)<>old.pin_hash) then raise exception 'Current PIN is incorrect'; end if; insert into public.datasub_transaction_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at) values(uid,extensions.crypt(p_pin,extensions.gen_salt('bf')),0,null,now()) on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now(); end$$;
revoke all on function public.set_datasub_transaction_pin(text,text) from public,anon; grant execute on function public.set_datasub_transaction_pin(text,text) to authenticated,service_role;
create or replace function public.verify_datasub_transaction_pin(p_user uuid,p_pin text) returns boolean language plpgsql security definer set search_path='' as $$declare x public.datasub_transaction_pins; ok boolean; begin if current_user not in ('service_role','postgres','supabase_admin') then raise exception 'Service role only'; end if; select * into x from public.datasub_transaction_pins where user_id=p_user for update; if x.user_id is null then return false; end if; if x.locked_until is not null and x.locked_until>now() then return false; end if; ok:=extensions.crypt(coalesce(p_pin,''),x.pin_hash)=x.pin_hash; if ok then update public.datasub_transaction_pins set failed_attempts=0,locked_until=null,updated_at=now() where user_id=p_user; else update public.datasub_transaction_pins set failed_attempts=case when failed_attempts>=4 then 0 else failed_attempts+1 end,locked_until=case when failed_attempts>=4 then now()+interval '15 minutes' else locked_until end,updated_at=now() where user_id=p_user; end if; return ok; end$$;
revoke all on function public.verify_datasub_transaction_pin(uuid,text) from public,anon,authenticated; grant execute on function public.verify_datasub_transaction_pin(uuid,text) to service_role;